// -----------------------------------------------------------------------------
// Helper: Universal Tool Call Extractor from textual content (Qwen/DeepSeek/Llama fallback)
// -----------------------------------------------------------------------------
function parseToolCallsFromContent(content) {
  if (!content || !content.trim()) return [];

  const toolCalls = [];

  // 1. <tool_call>...</tool_call> XML tags
  const toolCallTagRegex = /<tool_call>([\s\S]*?)<\/tool_call>/gi;
  let match;
  while ((match = toolCallTagRegex.exec(content)) !== null) {
    try {
      const parsed = JSON.parse(match[1].trim());
      const name = parsed.name || parsed.tool || parsed.function?.name;
      const args = parsed.arguments || parsed.parameters || parsed.function?.arguments || {};
      if (name) {
        toolCalls.push({
          id: `tc-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
          toolId: name,
          name,
          arguments: typeof args === 'string' ? JSON.parse(args) : args,
          rawCall: match[0]
        });
      }
    } catch {}
  }
  if (toolCalls.length > 0) return toolCalls;

  // 2. Markdown code blocks ```json ... ``` or ``` ... ```
  const codeBlockRegex = /```(?:json)?\s*([\s\S]*?)\s*```/gi;
  while ((match = codeBlockRegex.exec(content)) !== null) {
    try {
      const parsed = JSON.parse(match[1].trim());
      const items = Array.isArray(parsed) ? parsed : [parsed];
      for (const item of items) {
        const name = item.name || item.tool || item.function?.name;
        const args = item.arguments || item.parameters || item.function?.arguments;
        if (name && args) {
          toolCalls.push({
            id: `tc-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
            toolId: name,
            name,
            arguments: typeof args === 'string' ? JSON.parse(args) : args,
            rawCall: match[0]
          });
        }
      }
    } catch {}
  }
  if (toolCalls.length > 0) return toolCalls;

  // 3. Raw JSON object
  const trimmed = content.trim();
  if (trimmed.startsWith('{') && trimmed.endsWith('}')) {
    try {
      const parsed = JSON.parse(trimmed);
      const name = parsed.name || parsed.tool || parsed.function?.name;
      const args = parsed.arguments || parsed.parameters || parsed.function?.arguments;
      if (name && args) {
        toolCalls.push({
          id: `tc-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
          toolId: name,
          name,
          arguments: typeof args === 'string' ? JSON.parse(args) : args,
          rawCall: trimmed
        });
      }
    } catch {}
  }

  return toolCalls;
}

